//generated from Decision Table
import org.joda.time.LocalDate;
import org.joda.time.format.DateTimeFormat;
import org.joda.time.format.DateTimeFormatter;
import com.armedia.acm.plugins.casefile.model.CaseFile;
import java.util.Date;
import java.util.Calendar;
import org.springframework.expression.EvaluationContext;
import org.springframework.expression.Expression;
import org.springframework.expression.ExpressionParser;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.expression.spel.support.StandardEvaluationContext;
function String dateFormat(String fmt)
{
  return LocalDate.now().toString(DateTimeFormat.forPattern(fmt));
}

function Date addDays(int days)
{
  Calendar cal = Calendar.getInstance();
  cal.add(Calendar.DAY_OF_YEAR, days);
  return cal.getTime();
}

function Boolean evalSpring(String expression, Object obj)
{
    ExpressionParser ep = new SpelExpressionParser();
    Expression exp = ep.parseExpression(expression);
    EvaluationContext ec = new StandardEvaluationContext();

    Boolean evaluated = exp.getValue(ec, obj, Boolean.class);

    return evaluated;
}
// rule values at C22, header at C17
rule "Save Case File Rules_22"
	salience 65535
	when
		$caseFile: CaseFile(eval(evalSpring("caseNumber == null", $caseFile)))
	then
		$caseFile.setCaseNumber(dateFormat('yyyyMMdd') + '_' + $caseFile.getId());
end

// rule values at C23, header at C17
rule "Save Case File Rules_23"
	salience 65534
	when
		$caseFile: CaseFile(eval(evalSpring("container?.folder?.cmisFolderId == null", $caseFile)))
	then
		$caseFile.setEcmFolderPath('/Sites/acm/documentLibrary/Case Files/' + dateFormat('yyyyMMdd') + '_' + $caseFile.getId());
end

// rule values at C24, header at C17
rule "Save Case File Rules_24"
	salience 65533
	when
		$caseFile: CaseFile(eval(evalSpring("status == null", $caseFile)))
	then
		$caseFile.setStatus('DRAFT');
end

// rule values at C25, header at C17
rule "Save Case File Rules_25"
	salience 65532
	when
		$caseFile: CaseFile(eval(evalSpring("priority == null", $caseFile)))
	then
		$caseFile.setPriority('Medium');
end

// rule values at C26, header at C17
rule "Save Case File Rules_26"
	salience 65531
	when
		$caseFile: CaseFile(eval(evalSpring("dueDate == null", $caseFile)))
	then
		$caseFile.setDueDate(addDays(180));
end


